grammar(fill(s,[A],['soeur','patient-caractere'],[],'Восстановите показанную женскую форму черты терпеливая.','Ma sœur est ','ма сёр э́','','',[fr('patient','пасья(н)'),fr('patiente','пасья(н)т')],1,'Ma sœur est patiente','ма сёр э пасья́(н)т','Сохранена женская форма для сестры.','В описании сестры нужна изученная женская форма с конечным согласным, а не форма для брата.'))
